#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_item_id_is_namespaced_lowercase_with_no_spaces() {
        for tab in CREATIVE_TABS {
            for id in tab.items.iter().copied() {
                assert!(
                    id.starts_with("minecraft:"),
                    "{} in tab {} is not minecraft:-prefixed",
                    id,
                    tab.id
                );
                assert!(
                    !id.contains(' '),
                    "{} in tab {} contains a space",
                    id,
                    tab.id
                );
                assert_eq!(
                    id.to_lowercase(),
                    id.to_string(),
                    "{} in tab {} is not lowercase",
                    id,
                    tab.id
                );
            }
        }
    }

    #[test]
    fn tab_strip_positions_have_no_duplicates() {
        let mut seen = std::collections::HashSet::new();
        for tab in CREATIVE_TABS {
            let position = (tab.top_row, tab.column);
            assert!(
                seen.insert(position),
                "duplicate tab-strip position {:?} (tab {})",
                position,
                tab.id
            );
        }
    }
}
